questionvariables.text:
/* Design: classify points against the perpendicular bisector of AB. Entries [A, B, points, categories, trap row]; category 1 on, 2 nearer A, 3 nearer B. One row is on the locus, one (the trap) is directly above or below M. Source: original. */
q12: [[[-6,-5],[0,-3],[[-7,-4],[-5,2],[-3,-1],[-1,-3]],[2,1,3,3],3],[[-4,-1],[2,-3],[[-1,-5],[-2,-5],[3,0],[-5,2]],[3,1,3,2],1],[[-2,-2],[4,-6],[[-1,-1],[1,-2],[5,-6],[3,-1]],[2,2,3,1],2],[[-1,-4],[5,0],[[-2,-4],[-2,4],[4,0],[2,-4]],[2,1,3,2],4],[[0,0],[2,-4],[[1,1],[3,-4],[-1,-1],[-3,-4]],[2,3,2,1],1],[[-4,-3],[2,-7],[[-5,-3],[3,-8],[-1,-8],[3,1]],[2,3,3,1],3],[[0,-2],[4,-4],[[2,-1],[0,-7],[1,-3],[3,-5]],[2,1,2,3],1],[[-1,-3],[5,-5],[[6,-6],[2,-1],[-2,-4],[1,-7]],[3,2,2,1],2],[[-2,-4],[2,-2],[[0,-5],[3,-3],[-3,-4],[2,-7]],[2,3,2,1],1],[[-4,-6],[-2,0],[[-5,-5],[3,-5],[-3,-6],[-3,1]],[2,1,2,3],3]];
ix: 1+rand(10);
A: q12[ix][1]; B: q12[ix][2]; P: q12[ix][3]; cats: q12[ix][4]; tr: q12[ix][5];
M: (A+B)/2;
PA2: makelist((P[k][1]-A[1])^2+(P[k][2]-A[2])^2, k, 1, 4);
PB2: makelist((P[k][1]-B[1])^2+(P[k][2]-B[2])^2, k, 1, 4);
keys: ["on","nA","nB"];
/* row type: 1 on the locus, 2 the trap (directly above or below M), 3 plain */
ty: makelist(if is(cats[k]=1) then 1 else if is(k=tr) then 2 else 3, k, 1, 4);
kyl: makelist(keys[cats[k]], k, 1, 4);
/* diagnostic answer per row: an on-row marked nearer A; any other row marked on */
dg: makelist(if is(ty[k]=1) then "nA" else "on", k, 1, 4);
/* generic wrong answer per row (tests): on-row nearer B; other rows the other nearer */
gw: makelist(if is(ty[k]=1) then "nB" else if is(kyl[k]="nA") then "nB" else "nA", k, 1, 4);
mko(c) := [["on",is(c=1),"on the locus"],["nA",is(c=2),"nearer to A"],["nB",is(c=3),"nearer to B"]];
o1: mko(cats[1]); o2: mko(cats[2]); o3: mko(cats[3]); o4: mko(cats[4]);
ta1: kyl[1]; ta2: kyl[2]; ta3: kyl[3]; ta4: kyl[4];
